codeExamples.code:
-- Traversal privileges are required on every ancestor
GRANT USE CATALOG ON CATALOG prod TO `data-analysts`;
GRANT USE SCHEMA  ON SCHEMA  prod.sales TO `data-analysts`;

-- Read-only access to one table
GRANT SELECT ON TABLE prod.sales.orders TO `data-analysts`;

-- Engineers: traverse + read + write + create within the schema
GRANT USE CATALOG ON CATALOG prod TO `data-engineers`;
GRANT USE SCHEMA  ON SCHEMA  prod.sales TO `data-engineers`;
GRANT SELECT, MODIFY ON SCHEMA prod.sales TO `data-engineers`;  -- inherited by all current/future tables
GRANT CREATE TABLE ON SCHEMA prod.sales TO `data-engineers`;

-- Verify and clean up
SHOW GRANTS ON SCHEMA prod.sales;
REVOKE SELECT ON TABLE prod.sales.orders FROM `data-analysts`;

-- Assign ownership to a group, not an individual (survives personnel changes)
ALTER TABLE prod.sales.orders OWNER TO `sales-admins`;

-- Delegate management of a schema without transferring ownership
GRANT MANAGE ON SCHEMA prod.sales TO `sales-stewards`;

-- Service principal for an ETL job: minimal scoped privileges
GRANT USE CATALOG ON CATALOG prod TO `etl-prod-sp`;
GRANT USE SCHEMA ON SCHEMA prod.sales TO `etl-prod-sp`;
GRANT MODIFY ON TABLE prod.sales.orders TO `etl-prod-sp`;

-- Audit: who has what on this table, and all grants a group holds
SHOW GRANTS ON TABLE prod.sales.orders;
SELECT * FROM prod.information_schema.table_privileges
WHERE table_name = 'orders' AND table_schema = 'sales';
